func buildTrackWhere[Q psql.Filterable](cols trackColumns) trackWhere[Q] {
	return trackWhere[Q]{
		cols:       cols,
		ID:         psql.Where[Q, int32](cols.ID.Expression),
		Name:       psql.Where[Q, string](cols.Name.Expression),
		Country:    psql.WhereNull[Q, string](cols.Country.Expression),
		Latitude:   psql.WhereNull[Q, decimal.Decimal](cols.Latitude.Expression),
		Longitude:  psql.WhereNull[Q, decimal.Decimal](cols.Longitude.Expression),
		WebsiteURL: psql.WhereNull[Q, string](cols.WebsiteURL.Expression),
		IsActive:   psql.Where[Q, bool](cols.IsActive.Expression),
		CreatedAt:  psql.Where[Q, time.Time](cols.CreatedAt.Expression),
		UpdatedAt:  psql.Where[Q, time.Time](cols.UpdatedAt.Expression),
		CreatedBy:  psql.Where[Q, string](cols.CreatedBy.Expression),
		UpdatedBy:  psql.Where[Q, string](cols.UpdatedBy.Expression),
		R:          trackWhereR[Q]{cols: cols},
	}
}

// trackWhereR holds the relationship-based filters of
// trackWhere under the R namespace — mirroring the model's
// R struct — so they cannot collide with column-based filter fields.
type trackWhereR[Q psql.Filterable] struct {
	cols trackColumns
}

// HasTrackLayouts filters parents that have a matching TrackLayouts using a
// correlated EXISTS subquery (semi-join). Unlike an INNER JOIN it does not
// multiply parent rows, so no DISTINCT is needed. The optional filters are
// applied to the subquery (i.e. to TrackLayouts).
func (w trackWhereR[Q]) HasTrackLayouts(filters ...bob.Mod[*dialect.SelectQuery]) mods.Where[Q] {
	q := psql.Select(
		sm.Columns(psql.Raw("1")),
		sm.From(TrackLayouts.NameExpr()),
		sm.Where(TrackLayouts.Columns.TrackID.EQ(w.cols.ID)),
	)
	q.Apply(filters...)
	return mods.Where[Q]{E: psql.Exists(q)}
}

// NULL-tolerant scan buffer for trackScanMapperNullable:
// on a LEFT JOIN miss every column comes back NULL, so each field uses the
// nullable version of the column type even when the column itself is NOT NULL.
type trackPreloadBuf struct {
	ID         null.Val[int32]
	Name       null.Val[string]
	Country    null.Val[string]
	Latitude   null.Val[decimal.Decimal]
	Longitude  null.Val[decimal.Decimal]
	WebsiteURL null.Val[string]
	IsActive   null.Val[bool]
	CreatedAt  null.Val[time.Time]
	UpdatedAt  null.Val[time.Time]
	CreatedBy  null.Val[string]
	UpdatedBy  null.Val[string]
}

// trackScanMapperNullable maps the preloaded track
// columns (prefixed with the runtime join alias) without reflection, while
// keeping the LEFT JOIN semantics of the reflection-based mapper: a row whose
// prefixed columns are all NULL yields nil (no child), and NULL values never
// error, they just leave the zero value in the field.
func trackScanMapperNullable(prefix string) scan.Mapper[*Track] {
	return func(ctx context.Context, cols []string) (scan.BeforeFunc, func(any) (*Track, error)) {
		// resolve the column names once per query, not per row
		type target struct {
			idx int
			dst func(b *trackPreloadBuf) any
		}
		targets := make([]target, 0, 11)
		for i, col := range cols {
			name, ok := strings.CutPrefix(col, prefix)
			if !ok {
				continue
			}
			switch name {
			case "id":
				targets = append(targets, target{i, func(b *trackPreloadBuf) any { return &b.ID }})
			case "name":
				targets = append(targets, target{i, func(b *trackPreloadBuf) any { return &b.Name }})
			case "country":
				targets = append(targets, target{i, func(b *trackPreloadBuf) any { return &b.Country }})
			case "latitude":
				targets = append(targets, target{i, func(b *trackPreloadBuf) any { return &b.Latitude }})
			case "longitude":
				targets = append(targets, target{i, func(b *trackPreloadBuf) any { return &b.Longitude }})
			case "website_url":
				targets = append(targets, target{i, func(b *trackPreloadBuf) any { return &b.WebsiteURL }})
			case "is_active":
				targets = append(targets, target{i, func(b *trackPreloadBuf) any { return &b.IsActive }})
			case "created_at":
				targets = append(targets, target{i, func(b *trackPreloadBuf) any { return &b.CreatedAt }})
			case "updated_at":
				targets = append(targets, target{i, func(b *trackPreloadBuf) any { return &b.UpdatedAt }})
			case "created_by":
				targets = append(targets, target{i, func(b *trackPreloadBuf) any { return &b.CreatedBy }})
			case "updated_by":
				targets = append(targets, target{i, func(b *trackPreloadBuf) any { return &b.UpdatedBy }})
			}
		}

		// One scratch buffer reused for every row: before -> scan -> after runs
		// synchronously per row, the scheduled columns are fully overwritten each
		// row, and unselected columns stay zero, so a single buffer preserves the
		// per-row NULL semantics without allocating a buffer per parent row. The
		// returned child (o below) is always freshly allocated, so buf never
		// escapes past the after func.
		buf := new(trackPreloadBuf)
		return func(row *scan.Row) (any, error) {
				for _, t := range targets {
					row.ScheduleScanByIndex(t.idx, t.dst(buf))
				}
				return buf, nil
			}, func(link any) (*Track, error) {
				buf := link.(*trackPreloadBuf)

				// Same rule as the reflection mapper's row validator: the child
				// exists only if at least one of its columns is not NULL. Columns
				// not selected by the query are never scanned and stay invalid,
				// so this check also matches when only a subset is selected.
				if !(buf.ID.IsValue()) &&
					!(buf.Name.IsValue()) &&
					!(buf.Country.IsValue()) &&
					!(buf.Latitude.IsValue()) &&
					!(buf.Longitude.IsValue()) &&
					!(buf.WebsiteURL.IsValue()) &&
					!(buf.IsActive.IsValue()) &&
					!(buf.CreatedAt.IsValue()) &&
					!(buf.UpdatedAt.IsValue()) &&
					!(buf.CreatedBy.IsValue()) &&
					!(buf.UpdatedBy.IsValue()) {
					return nil, nil
				}

				o := new(Track)
				if buf.ID.IsValue() {
					o.ID = buf.ID.MustGet()
				}
				if buf.Name.IsValue() {
					o.Name = buf.Name.MustGet()
				}
				o.Country = buf.Country
				o.Latitude = buf.Latitude
				o.Longitude = buf.Longitude
				o.WebsiteURL = buf.WebsiteURL
				if buf.IsActive.IsValue() {
					o.IsActive = buf.IsActive.MustGet()
				}
				if buf.CreatedAt.IsValue() {
					o.CreatedAt = buf.CreatedAt.MustGet()
				}
				if buf.UpdatedAt.IsValue() {
					o.UpdatedAt = buf.UpdatedAt.MustGet()
				}
				if buf.CreatedBy.IsValue() {
					o.CreatedBy = buf.CreatedBy.MustGet()
				}
				if buf.UpdatedBy.IsValue() {
					o.UpdatedBy = buf.UpdatedBy.MustGet()
				}
				return o, nil
			}
	}
}

func (o *Track) Preload(name string, retrieved any) error {
	if o == nil {
		return nil
	}

	switch name {
	case "TrackLayouts":
		rels, ok := retrieved.(TrackLayoutSlice)
		if !ok {
			return fmt.Errorf("track cannot load %T as %q", retrieved, name)
		}

		o.R.TrackLayouts = rels
		o.R.Loaded.TrackLayouts = true

		for _, rel := range rels {
			if rel != nil {
				rel.R.Track = o
				rel.R.Loaded.Track = true
			}
		}
		return nil
	default:
		return fmt.Errorf("track has no relationship %q", name)
	}
}

