// LoadCountTrackLayouts loads the count of TrackLayouts for a slice in a single batch query
func (os TrackSlice) LoadCountTrackLayouts(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	// Build the IN arg expression from parent PKs

	pkID := make(pgtypes.Array[int32], 0, len(os))
	for _, o := range os {
		if o == nil {
			continue
		}
		pkID = append(pkID, o.ID)
	}
	PKArgExpr := psql.Any(psql.Cast(psql.Arg(pkID), "integer[]"))

	// countResult holds one scanned row from the batch count query.
	// FK columns are aliased to the parent PK column names for direct map lookup.
	type countResult struct {
		ID    int32
		Count int64
	}

	batchMods := []bob.Mod[*dialect.SelectQuery]{
		// SELECT fk AS parent_pk, count(*)
		sm.Columns(
			TrackLayouts.Columns.TrackID.As("id"),
			psql.Raw("count(*) as count"),
		),
		// Single-hop: FROM related table directly
		sm.From(TrackLayouts.NameAsExpr()),

		// WHERE fk IN (parent PKs) — psql single-column FK uses `= ANY(array)` (see PKArgExpr above)
		sm.Where(TrackLayouts.Columns.TrackID.EQ(PKArgExpr)),
		// GROUP BY fk columns
		sm.GroupBy(TrackLayouts.Columns.TrackID),
	}
	batchMods = append(batchMods, mods...)

	results, err := bob.All(ctx, exec,
		psql.Select(batchMods...),
		scan.StructMapper[countResult](),
	)
	if err != nil {
		return err
	}

	// Single-column FK: direct map lookup
	countMap := make(map[int32]int64, len(results))
	for _, r := range results {
		countMap[r.ID] = r.Count
	}
	for _, o := range os {
		if o == nil {
			continue
		}
		count := countMap[o.ID]
		o.C.TrackLayouts = &count
	}

	return nil
}

type trackJoins[Q dialect.Joinable] struct {
	typ          string
	TrackLayouts modAs[Q, trackLayoutColumns]
}

func (j trackJoins[Q]) aliasedAs(alias string) trackJoins[Q] {
	return buildTrackJoins[Q](buildTrackColumns(alias), j.typ)
}

func buildTrackJoins[Q dialect.Joinable](cols trackColumns, typ string) trackJoins[Q] {
	return trackJoins[Q]{
		typ: typ,
		TrackLayouts: modAs[Q, trackLayoutColumns]{
			c: TrackLayouts.Columns,
			f: func(to trackLayoutColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, TrackLayouts.NameExpr().As(to.Alias())).On(
						to.TrackID.EQ(cols.ID),
					))
				}

				return mods
			},
		},
	}
}
